window.NB_DEPOSITS_I18N.captureDefaults = function () {
  if (!document.body || !document.body.classList.contains('deposits-hub-page')) return;
  if (window.NB_DEPOSITS_I18N._defaultsCaptured) return;
  window.NB_DEPOSITS_I18N._defaultsCaptured = true;

  document.querySelectorAll('.deposits-account-panel [data-nb-i18n]').forEach(function (el) {
    if (!el.getAttribute('data-nb-i18n-default')) {
      el.setAttribute('data-nb-i18n-default', (el.textContent || '').trim());
    }
  });
  document.querySelectorAll('.deposits-hub-shell [data-nb-i18n]').forEach(function (el) {
    if (!el.getAttribute('data-nb-i18n-default')) {
      el.setAttribute('data-nb-i18n-default', (el.textContent || '').trim());
    }
  });
  document.querySelectorAll('.deposits-account-panel [data-nb-i18n-alt], .deposits-hub-shell [data-nb-i18n-alt]').forEach(function (el) {
    if (!el.getAttribute('data-nb-i18n-alt-default')) {
      el.setAttribute('data-nb-i18n-alt-default', el.getAttribute('alt') || '');
    }
  });
};

window.NB_DEPOSITS_I18N.applyAll = function (code) {
  if (!document.body || !document.body.classList.contains('deposits-hub-page')) return;

  const lang = code === 'hi' ? 'hi' : 'en';
  const uiDict = window.NB_I18N ? (window.NB_I18N[lang] || window.NB_I18N.en) : {};
  const depDict = window.NB_DEPOSITS_I18N[lang] || window.NB_DEPOSITS_I18N.en || {};
  const dict = Object.assign({}, uiDict, depDict);

  if (!window.NB_DEPOSITS_I18N._defaultsCaptured) {
    window.NB_DEPOSITS_I18N.captureDefaults();
  }

  document.documentElement.lang = lang === 'hi' ? 'hi' : 'en';
  document.body.setAttribute('data-nb-lang', lang);
  localStorage.setItem('nainital-lang', lang);

  function applyText(el) {
    const key = el.getAttribute('data-nb-i18n');
    if (!key) return;

    const fallback = el.getAttribute('data-nb-i18n-default');
    let text = dict[key];

    if (text === undefined || text === null) {
      if (lang === 'en' && fallback !== null) {
        el.textContent = fallback;
      }
      return;
    }

    text = String(text);
    if (el.hasAttribute('data-nb-i18n-br') || (text.indexOf('\n') !== -1 && el.tagName !== 'INPUT')) {
      el.innerHTML = text.split('\n').join('<br>');
    } else {
      el.textContent = text;
    }
  }

  document.querySelectorAll('.deposits-account-panel [data-nb-i18n]').forEach(applyText);
  document.querySelectorAll(
    '.deposits-hub-shell .deposits-sidebar [data-nb-i18n], .deposits-hub-shell .deposits-nav-mobile-wrap [data-nb-i18n]'
  ).forEach(applyText);

  document.querySelectorAll('.deposits-account-panel [data-nb-i18n-alt], .deposits-hub-shell [data-nb-i18n-alt]').forEach(function (el) {
    const key = el.getAttribute('data-nb-i18n-alt');
    if (!key) return;
    const fallback = el.getAttribute('data-nb-i18n-alt-default');
    const alt = dict[key];
    if (alt === undefined || alt === null) {
      if (lang === 'en' && fallback !== null) el.alt = fallback;
      return;
    }
    el.alt = String(alt);
  });

  const meta = document.querySelector('meta[name="description"]');
  if (dict['page.title.deposits']) document.title = dict['page.title.deposits'];
  if (meta && dict['page.description.deposits']) meta.setAttribute('content', dict['page.description.deposits']);
};

(function () {
  if (document.body && document.body.classList.contains('deposits-hub-page')) {
    window.NB_DEPOSITS_I18N.captureDefaults();
  }
})();
